-- ACTUALIZACION SOLO RMA para prueba.lineas_unificadas
-- 7711 filas del volcado historico del 17-11-2026.
-- NO importa Productos/Test ni modifica las tablas originales.
-- Requiere prueba.lineas_unificadas y prueba.tipo_registro (id=3).
-- Hacer una copia de seguridad antes de ejecutar.
-- La importacion se hace en grupos de 250; cada grupo se confirma automaticamente.
-- Si se corta la ejecucion, el archivo puede ejecutarse de nuevo: omite IDs RMA existentes.
USE `prueba`;
SET NAMES utf8mb4;
DROP TEMPORARY TABLE IF EXISTS `_import_rma_20261117`;
DROP TEMPORARY TABLE IF EXISTS `_rma_ya_existentes`;

CREATE TEMPORARY TABLE `_import_rma_20261117` (
  `idLineas_rma` bigint(20) NOT NULL,
  `NPedido` int(11) NOT NULL,
  `rma` varchar(30) NOT NULL,
  `CMMF` varchar(20) NOT NULL,
  `referencia` varchar(40) NOT NULL,
  `descripcion` varchar(200) NOT NULL,
  `woPortugal` varchar(50) NOT NULL,
  `mr` varchar(5) NOT NULL,
  `alarma` varchar(100) NOT NULL,
  `facturado` varchar(20) NOT NULL,
  `motivoRechazo` varchar(200) NOT NULL,
  `udPedido` int(11) NOT NULL,
  `udAnuladas` int(11) NOT NULL,
  `udAlbaran` int(11) NOT NULL,
  `codFamilia` int(11) NOT NULL,
  `subCodFamilia` varchar(8) NOT NULL,
  `descripcionMarca` varchar(100) NOT NULL,
  `llegada` varchar(10) NOT NULL,
  `codBarrasSeb` varchar(15) NOT NULL,
  `noAbono` varchar(50) NOT NULL,
  `movChManual` varchar(100) NOT NULL,
  `fechaMovChManual` date DEFAULT NULL,
  PRIMARY KEY (`idLineas_rma`)
) ENGINE=InnoDB DEFAULT CHARSET=UTF8MB4;



-- Comprobar datos de origen y facilitar una busqueda de duplicados rapida.
SELECT COUNT(*) AS filas_fuente_rma FROM `_import_rma_20261117`;
CREATE TEMPORARY TABLE `_rma_ya_existentes` (
  `idLineas_rma` BIGINT NOT NULL PRIMARY KEY
) ENGINE=InnoDB;
SELECT DISTINCT `idLineas_rma`
FROM `lineas_unificadas`
WHERE `idLineas_rma` IS NOT NULL;

-- Bloque 1 de 31; 250 registros de origen
  `tipoRegistro`, `idLineas_rma`, `NPedido`, `rma`, `CMMF`, `referencia`, `descripcion`, `woPortugal`, `mr`, `alarma`, `facturado`, `motivoRechazo`, `udPedido`, `udAnuladas`, `udAlbaran`, `codFamilia`, `subCodFamilia`, `descripcionMarca`, `llegada`, `codBarrasSeb`, `noAbono`, `movChManual`, `fechaMovChManual`
)
SELECT 3, src.`idLineas_rma`, src.`NPedido`, src.`rma`, src.`CMMF`, src.`referencia`, src.`descripcion`, src.`woPortugal`, src.`mr`, src.`alarma`, src.`facturado`, src.`motivoRechazo`, src.`udPedido`, src.`udAnuladas`, src.`udAlbaran`, src.`codFamilia`, src.`subCodFamilia`, src.`descripcionMarca`, src.`llegada`, src.`codBarrasSeb`, src.`noAbono`, src.`movChManual`, src.`fechaMovChManual`
FROM `_import_rma_20261117` src
LEFT JOIN `_rma_ya_existentes` e ON e.`idLineas_rma` = src.`idLineas_rma`
WHERE src.`idLineas_rma` BETWEEN 8410011536061 AND 8410011538553
  AND e.`idLineas_rma` IS NULL;

